{
  "title": "图书馆的误会",
  "scene": "你和好友小明约好在图书馆见面，准备一起复习明天的期末考试。当你到达图书馆时，小明正和一个你不太认识的学长在低声交谈，看起来有些紧张。你注意到学长手里拿着一本厚厚的参考书，而小明的书包里似乎也有类似的东西。你决定采取行动。",
  "goal": "找到小明，一起复习考试。",
  "clue": "学长手里拿着的参考书和小明书包里的东西。",
  "choices": [
    {
      "id": "A",
      "text": "直接走过去，打断他们的对话。",
      "outcome": "小明看起来有些尴尬，学长也显得不高兴。你们俩一起复习的计划受到了影响，小明似乎需要时间来缓和气氛。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "静悄悄地坐在旁边，假装看书。",
      "outcome": "过了一会儿，小明主动过来和你解释，原来学长在帮他解决一个难题。你们顺利开始了复习，还从学长那里得到了一些宝贵的建议。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "远远地打电话给小明。",
      "outcome": "小明接电话的瞬间，学长显得很不高兴，他认为你们在打扰他的学习。你们之间的误会加深了，复习计划不得不重新安排。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
